document.addEventListener('click',event=>{
  if(event.target.closest('#navigation a,.brand')){closeNavigation(false);if(event.target.closest('a').hash===location.hash)main.focus({preventScroll:true});}
  const target=event.target.closest('[data-action]');if(!target||target.disabled)return;
  const action=target.dataset.action;
  if(extensionActions.has(action)){extensionActions.get(action)(target,event);return;}
  if(simpleDetails[action]){const [title,sub,body,next]=simpleDetails[action];showDetail(title,sub,`<div class="detail-section"><h3>当前依据</h3><p>${body}</p></div><div class="callout">${next}</div>`,button('返回原位置','close-detail'));return;}
  switch(action){
    case 'navigate': location.hash=target.dataset.route;break;
    case 'close-detail':closeDetail();break;
    case 'close-modal':closeModal();break;
    case 'portfolio-mode':state.portfolioMode=target.dataset.mode;state.portfolioUserChoice=true;render();break;
    case 'project':{const p=projects.find(item=>item.id===target.dataset.id);showDetail(p.name,p.description,`<div class="detail-section"><dl><dt>负责团队</dt><dd>${p.owner}</dd><dt>交付范围</dt><dd>${p.accepted} / ${p.total} 项已验收</dd><dt>应用</dt><dd>${p.app}</dd><dt>下个里程碑</dt><dd>${p.date} · 计划日期</dd></dl></div><div class="callout">${p.risk}。查看事项后返回，保留项目搜索与团队筛选。</div>`,button('返回项目列表','close-detail'));break;}
    case 'attention-plan':showDetail('周弈的排期需要协调','TASK-108 / TASK-112 · 示例冲突',`<div class="detail-section"><h3>阻塞原因</h3><p>两个任务的计划安排重叠。先查看完整任务与可用日历，再决定改期或重新分配。</p></div><div class="detail-section"><h3>处理边界</h3><p>排期修改进入草稿，已验收任务只读；保存排期不会自动开始执行。</p></div>`,button('进入共享排期','navigate','primary','data-route="planning"'));break;
    case 'attention-requirement':location.hash='requirements';setTimeout(suggestion,0);break;
    case 'metric':{const explanations={accepted:'人工验收 18 项 / 当前交付范围 26 项。范围变化和验收增长分别统计。',running:'当前有 5 项执行中，等待资源与等待依赖不算正在执行。',testing:'1 项待测试、1 项测试失败，合计 2 项。失败不等于整个项目失败。',review:'1 项已有独立测试结果、等待具有权限的人员验收。'};showDetail('交付指标明细','星云商业平台 / 当前交付范围',`<div class="detail-section"><p>${explanations[target.dataset.id]}</p></div><div class="callout">这是样稿指标定义，不是实时统计；正式实现由授权汇总接口提供准确范围。</div>`,button('查看质量追溯示例','navigate','','data-route="quality"'));break;}
    case 'planning-preview':showModal('智能规划 · 明确目标与边界','<p class="prose">建议将支付恢复、审核体验与回归用例组成一个交付范围。示例建议不调用模型，不创建任务。</p><div class="checklist"><label><input type="checkbox" checked disabled>保留已有需求、标准与依赖</label><label><input type="checkbox" checked disabled>只对未开始任务提出排期建议</label><label><input type="checkbox" checked disabled>人工验收与生产发布保留独立关口</label></div>',button('查看排期样例','open-planning','primary'));break;
    case 'open-planning':closeModal();location.hash='planning';break;
    case 'chapter':state.chapter=target.dataset.id;render();break;
    case 'suggestion':suggestion();break;
    case 'apply-suggestion':if(!$('#suggestion-consent').checked){toast('请先确认这是假设未确认的草稿建议。');$('#suggestion-consent').focus();break;}if(!state.suggestionApplied){state.requirement.body+='\n\n验收补充：先核对原支付结果，明确未支付后才允许创建新请求。待确认：提供方查询能力。';state.suggestionApplied=true;}state.requirementDirty=true;closeModal();render();toast('建议已加入本地草稿；尚未正式发布。');break;
    case 'save-requirement':state.requirementDirty=false;render();toast('已保存到当前样稿内存；刷新会恢复示例。');break;
    case 'publish-check':showModal('发布前检查 · 样稿',`<div class="callout amber spaced">仍有待确认假设，当前不能视为完整设计验收。</div><ul class="rule-list"><li>${icon('warning')}提供方查询能力尚未验证</li><li>${icon('doc')}AC-PAY-01 r2 需要影响评估</li><li>${icon('lock')}正式发布需当前授权、版本检查与操作 ID</li></ul>`);break;
    case 'task-diff':showModal('任务采用差异 · 样稿','<div class="diff-row"><div class="diff-side"><small>更新 · TASK-108</small><p>补充未知支付结果的核对要求。</p></div><div class="diff-side"><small>保留 · TASK-118</small><p>保留既有独立回归任务。</p></div></div><div class="callout">新增 0 / 更新 1 / 保留 1 / 移出 0。正式采用沿现有原子合同；样稿不提交任务。</div>');break;
    case 'plan-view':state.planView=target.dataset.mode;render();break;
    case 'schedule':schedule(target.dataset.id);break;
    case 'schedule-save':{const form=$('#schedule-form');if(!form.reportValidity())break;const start=Number(form.elements.start.value.slice(-2)),end=Number(form.elements.end.value.slice(-2));if(start>end){$('#schedule-error').textContent='结束日期不能早于开始日期。';break;}const task=state.tasks.find(t=>t.id===target.dataset.id);const dependency=state.tasks.find(t=>t.id===task.dependency);const dependent=state.tasks.find(t=>t.dependency===task.id&&t.start<=end);if(dependency&&start<=dependency.end){$('#schedule-error').textContent=`开始日期必须晚于前置任务结束日期 10/${dependency.end}。`;break;}if(dependent){$('#schedule-error').textContent=`结束日期必须早于后置任务 ${dependent.id} 的开始日期 10/${dependent.start}。`;break;}task.start=start;task.end=end;const saved=state.savedTasks.find(t=>t.id===task.id);if(start===saved.start&&end===saved.end)state.planChanges.delete(task.id);else state.planChanges.add(task.id);closeModal();render();toast('已更新共享排期草稿，尚未保存。');break;}
    case 'undo-plan':state.tasks=structuredClone(state.savedTasks);state.planChanges.clear();render();toast('已撤销本次排期草稿。');break;
    case 'plan-diff':planDiff();break;
    case 'save-plan':state.savedTasks=structuredClone(state.tasks);state.planChanges.clear();closeModal();render();toast('样稿排期已保存到内存；没有提交实际项目。');break;
    case 'replan':showModal('重规划建议 · 预设样例','<p class="prose">建议把支付恢复从 10/12—10/16 调整到 10/10—10/13，减少与审核交互的重叠。保留依赖、验收历史与固定基线。</p><div class="diff-row"><div class="diff-side"><small>原排期</small>TASK-108：10/12—10/16</div><div class="diff-side new"><small>建议排期</small>TASK-108：10/10—10/13</div></div><div class="callout">没有模型调用。实际重规划须重验日历、来源、权限与预算；当前样稿只更新一个未开始任务。</div>',button('采用到排期草稿','apply-replan','primary'));break;
    case 'apply-replan':{const task=state.tasks.find(t=>t.id==='TASK-108');task.start=10;task.end=13;const saved=state.savedTasks.find(t=>t.id===task.id);if(saved.start!==10||saved.end!==13)state.planChanges.add(task.id);else state.planChanges.delete(task.id);closeModal();render();toast('建议进入共享草稿；仍需审阅与保存。');break;}
    case 'capacity-detail':{const start=Number(target.dataset.week),list=filteredTasks().filter(t=>t.owner===target.dataset.owner&&t.start<=start+6&&t.end>=start);showDetail(`${target.dataset.owner} · 周容量`,`${calendarDay(start)}—${calendarDay(start+6)} · 与当前筛选相同范围`,`<div class="detail-section"><h3>本周涉及任务</h3>${list.length?list.map(t=>`<p>${button(t.title,'schedule','row-link',`data-id="${t.id}"`)}<br><small>10/${t.start}—10/${t.end} · 总估算 ${t.hours}h</small></p>`).join(''):'<p>当前范围没有计划任务。</p>'}</div><div class="callout">计划分配不等于实际工时。人员容量与 Agent 并发分别展示。</div>`);break;}
    case 'dispatch-candidates':showDetail('能力匹配解释','TASK-108 · 确定性过滤优先',`<div class="detail-section"><h3>符合条件</h3><p>原生 Agent / Octop：当前项目授权、Go 能力与网关范围符合要求。</p></div><div class="detail-section"><h3>仍需确认</h3><p>Codex：已有适配；当前计划若要求强制费用上限，需要独立核验工具预算语义。</p></div><div class="detail-section"><h3>尚未适配</h3><p>Cursor / Claude Code / Qoder：本仓库暂无对应执行适配，不能加入可执行候选。</p></div><div class="callout">没有可信历史时只显示符合条件；不编造质量分或成功率。</div>`,button('审阅派发计划','dispatch','primary'));break;
    case 'dispatch':showModal('固定计划审阅 · 派发预览','<p class="prose">TASK-108 · 原生 Agent · 项目 Runner 池 · 设计修订 3</p><div class="form-grid"><div class="callout">执行范围<br>支付恢复 / 独立工作树 / 固定工具</div><div class="callout">预算与门禁<br>示例预留 ¥40 / 最多修复 1 次</div></div><ul class="rule-list"><li>'+icon('lock')+'启动时重验当前授权、来源、预算与可用槽位</li><li>'+icon('shield')+'独立测试、人工验收与生产发布各自保留</li></ul><div class="callout amber spaced">设计稿没有服务器连接。确认只演示审阅回执，不会创建运行。</div>',button('确认样稿计划','confirm-demo-dispatch','primary'));break;
    case 'confirm-demo-dispatch':closeModal();showDetail('样稿计划已确认','本地交互记录 · 没有创建运行','<div class="detail-section"><dl><dt>运行事实</dt><dd>未提交</dd><dt>外部调用</dt><dd>无</dd><dt>正式下一步</dt><dd>真实产品应等待服务器的固定计划与启动回执。</dd></dl></div>');break;
    case 'automation-preview':showModal('自动化规则 · 只读匹配预览','<div class="flow-steps"><span>独立测试失败</span><span>当前固定候选</span><span>权限 / 预算</span><span>生成修复提案</span></div><div class="callout">示例匹配：RUN-061。辅助模式只生成建议；受控执行需要原策略已授权的固定范围。</div><ul class="rule-list"><li>'+icon('warning')+'同一失败指纹连续两次：停止自动修复</li><li>'+icon('warning')+'外部效果未知：核对，禁止盲目重试</li><li>'+icon('lock')+'模型不能自行提高预算或扩大权限</li></ul>');break;
    case 'tool-detail':{const tool=tools.find(t=>t.name===target.dataset.name);showDetail(tool.name,tool.entry,`<div class="detail-section"><dl><dt>当前状态</dt><dd>${pill(tool.status,tool.tone)}</dd><dt>方向</dt><dd>${tool.direction}</dd><dt>控制</dt><dd>${tool.control}</dd><dt>预算</dt><dd>${tool.budget}</dd><dt>生产验收</dt><dd>未由本设计稿证明</dd></dl></div><div class="callout">${tool.description} 完整官方依据见开发工具接入矩阵。</div>`,button('预览此接入向导','connect-wizard','primary',`data-name="${tool.name}"`));break;}
    case 'connect-wizard':state.wizardStep=0;state.wizardTool=target.dataset.name||'Codex';wizard();break;
    case 'wizard-back':state.wizardStep--;wizard();break;
    case 'wizard-next':if(state.wizardStep===2){closeModal();toast('已完成样稿选择；未安装、探测、授权或启用实际工具。');}else{state.wizardStep++;wizard();}break;
    case 'release-cell':showDetail(`${target.dataset.app} / ${target.dataset.env}`,'应用版本、部署与健康分别核对',`<div class="detail-section"><dl><dt>固定版本</dt><dd>${target.dataset.env==='生产'?'v1.3.2':'v1.4.0-rc.2'}</dd><dt>制品来源</dt><dd>示例固定提交 c7a29d8</dd><dt>批准</dt><dd>需对应环境当前批准</dd><dt>健康</dt><dd>独立观察窗口与证据有效期</dd><dt>回滚</dt><dd>需核对制品与数据变更资格</dd></dl></div><div class="callout">单元格展示样稿状态，不是实际环境查询。</div>`,button('查看发布检查','release-review'));break;
    case 'release-review':showModal('发布前检查 · 不执行部署','<div class="callout amber spaced">当前样例有过期标准证据与尚未完成的批准，不能宣称可发布。</div><ul class="rule-list"><li>'+icon('doc')+'固定应用版本、制品与环境</li><li>'+icon('shield')+'当前人工验收与发布批准</li><li>'+icon('layers')+'依赖批次、部分成功与原操作恢复</li><li>'+icon('refresh')+'健康观察窗口与独立回滚资格</li></ul>');break;
    case 'asset-tab':state.assetTab=target.dataset.id;render();break;
    case 'asset-diff':showModal('知识升级 · 采用预览','<div class="diff-row"><div class="diff-side"><small>项目当前采用 r4</small><p>超时记录后进入人工处理。</p></div><div class="diff-side new"><small>目录新修订 r5</small><p>补充原请求核对步骤；无法确认时继续保留未知。</p></div></div><div class="callout">适用范围：支付异常恢复。来源：已验收任务；评测与当前权限仍需确认。此处不改实际项目采用关系。</div>',button('记录样稿审阅','asset-reviewed','primary'));break;
    case 'asset-reviewed':closeModal();toast('已记录本地审阅演示；正式采用关系未改变。');break;
    case 'deployment':state.deployment=target.dataset.id;render();break;
    case 'config-diff':showModal('配置来源与变更预览','<div class="diff-row"><div class="diff-side"><small>组织默认</small><p>辅助模式 · 修复 1 次 · 网络白名单</p></div><div class="diff-side new"><small>项目拟覆盖</small><p>仍需在组织授权范围内；当前没有正式配置修改。</p></div></div><div class="callout">权限取交集、预算取已授权上限、秘密只传引用。固定计划不随模板修改静默变化。</div>');break;
    case 'apply-policy':state.automation=state.pendingAutomation;state.pendingAutomation=null;closeModal();render();toast('已更新样稿策略选择；未授权任何真实自动化。');break;
  }
});
document.addEventListener('input',event=>{const id=event.target.id,value=event.target.value;if(id==='project-query'){state.query=value;$('#project-results').innerHTML=projectResults();}if(id==='tool-query'){state.toolQuery=value;$('#tool-results').innerHTML=toolResults();}if(id==='requirement-title'||id==='requirement-body'){state.requirement[id==='requirement-title'?'title':'body']=value;state.requirementDirty=true;$('#requirement-save-state').textContent='草稿已修改，尚未保存到样稿状态';}});
document.addEventListener('change',event=>{const id=event.target.id,value=event.target.value;if(id==='project-owner'){state.owner=value;$('#project-results').innerHTML=projectResults();}if(id==='plan-owner'||id==='plan-status'){state[id==='plan-owner'?'planOwner':'planStatus']=value;$('#plan-content').innerHTML=planContent();}if(id==='tool-filter'){state.toolFilter=value;$('#tool-results').innerHTML=toolResults();}if(id==='wizard-tool'){state.wizardTool=value;wizard();}if(id==='wizard-scope')state.wizardScope=value;if(id==='automation-mode'){state.pendingAutomation=value;event.target.value=state.automation;const names={assist:'辅助模式',controlled:'受控执行',maintenance:'自主维护'};showModal(`策略变更预览：${names[value]}`,`<p class="prose">当前：${names[state.automation]}。拟选择：${names[value]}。</p><div class="callout amber spaced">这是本地设计演示，不授予任何真实权限。正式策略必须绑定主体、项目、资源、动作、预算、并发与有效期。</div><ul class="rule-list"><li>${icon('lock')}正式验收、生产发布、权限提升始终保留人审</li><li>${icon('warning')}范围、模型、来源或预算变化须重新决策</li></ul>`,button('采用样稿策略','apply-policy','primary'));}});
$('#menu-toggle').innerHTML=icon('menu');$('#theme-toggle').innerHTML=icon('moon');$('#help-button').innerHTML=icon('help');
$('#menu-toggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('mobile-open');$('#menu-toggle').setAttribute('aria-expanded',String(open));if(open){$('#sidebar').setAttribute('role','dialog');$('#sidebar').setAttribute('aria-modal','true');$('.workspace').inert=true;document.body.style.overflow='hidden';$('#nav-close').focus();}else closeNavigation();});
$('#nav-close').addEventListener('click',()=>closeNavigation());
$('#theme-toggle').addEventListener('click',()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';$('#theme-toggle').innerHTML=icon(dark?'sun':'moon');$('#theme-toggle').setAttribute('aria-label',dark?'切换为浅色主题':'切换为深色主题');});
$('#help-button').addEventListener('click',()=>showModal('关于这份交互设计稿','<p class="prose">这是面向讨论与评审的可点击设计样稿。项目、日期、金额、任务与结果均为示例。页面不读取秘密、不连接真实服务，也不执行模型调用、任务派发或部署。</p><div class="callout spaced">试用路径：组织交付台 → 协调排期 → 审阅派发 → 质量与发布。草稿在页面切换中保留，刷新后恢复初始示例。</div><p class="prose spaced">十二个工作区入口用于集中演示跨领域流程，不替换当前产品的组织／项目导航。范围、实现状态与官方来源分别见统一体验设计、编排架构和开发工具接入矩阵。</p>'));
$('#drawer-backdrop').addEventListener('click',()=>closeDetail());
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if(!$('#detail').hidden)closeDetail();closeNavigation();}const trap=!$('#detail').hidden?$('#detail'):$('#sidebar').classList.contains('mobile-open')?$('#sidebar'):null;if(event.key==='Tab'&&trap){const focusable=[...trap.querySelectorAll('button:not(:disabled),a[href],input,select,textarea')].filter(el=>el.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
window.matchMedia('(max-width:767px)').addEventListener('change',event=>{if(!event.matches)closeNavigation(false);if(!state.portfolioUserChoice){state.portfolioMode=event.matches?'cards':'table';if(state.route==='portfolio')render();}});
window.SumaPrototype={state,icon,button,pill,section,heading,showDetail,showModal,closeModal,closeDetail,toast,escapeHTML,render,navigate,
  baseView(id){return {portfolio,requirements,planning,execution,connections,quality,assets,configuration}[id]();},
  registerViews(views){for(const view of views){if(!navItems.some(item=>item[0]===view.id))navItems.push([view.id,view.icon||'grid',view.title,view.eyebrow||view.id.toUpperCase()]);extensionViews.set(view.id,view.render);}},
  registerAction(name,handler){extensionActions.set(name,handler);},
  start(){state.route=navItems.some(item=>item[0]===location.hash.slice(1))?location.hash.slice(1):'portfolio';render();}
};
